wb = openpyxl.load_workbook(EXCEL, read_only=True)
ws = wb[wb.sheetnames[0]]
rows = {}
for r in ws.iter_rows(min_row=2):
    if r[0].value is not None and int(r[0].value) in CONF:
        rows[int(r[0].value)] = [c.value for c in r]

with open(JSON_PATH, encoding="utf-8") as f:
    data = json.load(f)

# 删除已存在（含之前误判为无预警的133）的同_index，准备重写
before = len(data)
data = [d for d in data if d.get("_index") not in CONF]
removed = before - len(data)

added = 0
for idx in sorted(CONF):
    v = rows[idx]
    d = dict(zip(cols, v))
    c = CONF[idx]
    title = (d["标题"] or "").strip()
    district = (d["区县"] or "待核实")
    pub = (d["发布日期"] or "待核实")
    url = (d["URL"] or "待核实")
    summ = (d["内容摘要"] or "").strip()
    src = "海阳市人民政府" if district=="海阳市" else ("烟台市牟平区人民政府" if district=="牟平区" else "莱山区人民政府")
    need_bs = "无" if c["bt"]=="无需" else "有"
    ai_reason = "【项目本质】%s。【基站需求】%s。【商机情报】%s" % (c["nf"], c["bsn"], c["biz"])
    ai_summary = "%s（%s），%s。" % (title, d.get("项目性质") or "待核实", c["wl"])
    entry = {
        "project_name": title,
        "project_type": (d["项目性质"] or "待核实"),
        "district": district,
        "location": c["loc"],
        "scale": c["scale"],
        "investment": c["inv"],
        "content": summ if summ else title,
        "developer": c["dev"],
        "contact_person": "待核实",
        "contact_phone": "待核实",
        "deadline": "待核实",
        "start_date": "待核实",
        "end_date": "待核实",
        "need_base_station": need_bs,
        "base_station_type": c["bt"],
        "coverage_area": c["loc"],
        "ai_reason": ai_reason,
        "priority": c["pr"],
        "score": c["sc"],
        "warning_level": c["wl"],
        "is_valuable": c["wl"] != "无预警",
        "telecom_needs": [c["bsn"]],
        "ai_summary": ai_summary,
        "source_name": src,
        "source_url": url,
        "publish_date": pub,
        "status": c["st"],
        "_index": idx,
        "_title": title,
    }
    data.append(entry)
    added += 1

with open(JSON_PATH, "w", encoding="utf-8") as f:
    json.dump(data, f, ensure_ascii=False, indent=2)

print("删除旧同_index条目:", removed, "| 本次追加建设类:", added)
print("workbuddy.json 现总条数:", len(data))
print("红色预警:", sum(1 for d in data if d["warning_level"]=="红色预警"),
      "| 黄色预警:", sum(1 for d in data if d["warning_level"]=="黄色预警"),
      "| 无预警:", sum(1 for d in data if d["warning_level"]=="无预警"))
